import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.Bb5YUzRP.js";import{Ai as i,Bi as a,Ci as o,Di as s,Ei as c,Fi as l,Gi as u,Hi as d,Ii as f,Ji as p,Ki as m,Li as h,Mi as g,Ni as _,Oi as v,Pi as y,Ri as b,Si as x,Ti as S,Ui as C,Vi as w,Wi as T,_i as ee,bi as E,ji as D,ki as O,qi as k,vi as A,wi as j,xi as M,yi as N,zi as P}from"./chunks/assets.juLBFQPb.js";var F=JSON.parse(`{"title":"Fields","description":"","frontmatter":{},"headers":[],"relativePath":"product-config/fields.md","filePath":"product-config/fields.md"}`),I={name:`product-config/fields.md`},L=p+` 1x, `+k+` 2x`,R=m+` 1x, `+u+` 2x`,z=T+` 1x, `+C+` 2x`,B=d+` 1x, `+w+` 2x`,V=a+` 1x, `+P+` 2x`,H=b+` 1x, `+h+` 2x`,U=f+` 1x, `+l+` 2x`,W=y+` 1x, `+_+` 2x`,G=g+` 1x, `+D+` 2x`,K=i+` 1x, `+O+` 2x`,q=v+` 1x, `+s+` 2x`,J=c+` 1x, `+S+` 2x`,Y=j+` 1x, `+o+` 2x`,X=x+` 1x, `+M+` 2x`,Z=E+` 1x, `+N+` 2x`,Q=A+` 1x, `+ee+` 2x`;function $(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to “Fields”">​</a></h1><p>Product fields are rectangles that can contain design elements (texts or images)</p><p>You can enable the fields feature and add the various fields to the designer.</p><p>In this example, we will add two fields, one for text and one for an image.</p><h2 id="adding-fields" tabindex="-1">Adding fields <a class="header-anchor" href="#adding-fields" aria-label="Permalink to “Adding fields”">​</a></h2><p>1️⃣ We start by adding the two fields by clicking the add button <img src="/webp/add-field-btn.jpg-90-1788222796634.webp" srcset="`+L+`" alt="Add field btn" title="" width="128" height="72" loading="lazy" style="width:64px;"></p><p><img src="/webp/product-fields.jpg-90-1788222796832.webp" srcset="`+R+`" alt="Product fields" title="" width="1590" height="1766" loading="lazy" style="width:795px;"></p><h2 id="editing-fields" tabindex="-1">Editing fields <a class="header-anchor" href="#editing-fields" aria-label="Permalink to “Editing fields”">​</a></h2><p>To edit a field, click the edit button</p><p><img src="/webp/edit-field-btn.jpg-90-1788222796698.webp" srcset="`+z+`" alt="Edit field btn" title="" width="634" height="434" loading="lazy" style="width:317px;"></p><p>This modal will be displayed</p><p><img src="/webp/edit-field-modal.jpg-90-1788222796699.webp" srcset="`+B+`" alt="Edit field modal" title="" width="668" height="1492" loading="lazy" style="width:334px;"></p><h2 id="field-type" tabindex="-1">Field type <a class="header-anchor" href="#field-type" aria-label="Permalink to “Field type”">​</a></h2><p>2️⃣ Next we change the fields properties to make them only accept a certain type of item ( optional)</p><p><img src="/webp/field-edit.jpg-90-1788222796701.webp" srcset="`+V+`" alt="Field edit" title="" width="656" height="1438" loading="lazy" style="width:328px;"></p><h2 id="text-field" tabindex="-1">Text field <a class="header-anchor" href="#text-field" aria-label="Permalink to “Text field”">​</a></h2><p>3️⃣ We enable the text field option on the first field and we set the label</p><p><img src="/webp/edit-text-field.jpg-90-1788222796700.webp" srcset="`+H+`" alt="Edit text field" title="" width="670" height="1492" loading="lazy" style="width:335px;"></p><p>The label will be be displayed like this</p><p><img src="/webp/field-label.jpg-90-1788222796702.webp" srcset="`+U+`" alt="Field label" title="" width="662" height="250" loading="lazy" style="width:331px;"></p><p>The text field will be displayed like this</p><p><img src="/webp/text-field-display.jpg-90-1788222796894.webp" srcset="`+W+`" alt="Text field display" title="" width="1838" height="702" loading="lazy" style="width:919px;"></p><h3 id="preferred-text-size" tabindex="-1">Preferred text size <a class="header-anchor" href="#preferred-text-size" aria-label="Permalink to “Preferred text size”">​</a></h3><p>By default, the text is scaled to fit the field, which means that its final size depends on how much text the customer types. If you want the text to be printed at a fixed physical size instead, set the <strong>Preferred text size (pt)</strong> option in the field settings.</p><p>The option is available on fields that have the <strong>Display as text field</strong> option enabled. Leave it at <code>0</code> to keep the automatic behaviour.</p><p>When a size is set:</p><ul><li>The text is rendered at that exact size in points, no matter how much text is entered</li><li>Long text wraps onto a new line at the field width instead of shrinking to fit</li></ul><p><img src="/webp/preferred-text-size.png-90-1788222796815.webp" srcset="`+G+`" alt="Preferred text size" title="" width="1294" height="660" loading="lazy" style="width:647px;"></p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>The size is converted using the <a href="/product-config/real-size.html">real size</a> of the side, so make sure the real size is configured correctly, otherwise the printed text will not match the requested size.</p></div><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>The preferred size is ignored for vertical and curved texts. They fall back to the normal text rendering.</p></div><h2 id="image-field" tabindex="-1">Image field <a class="header-anchor" href="#image-field" aria-label="Permalink to “Image field”">​</a></h2><p>4️⃣ We set the stretch image option on the image field. This will make any image we add to the field fill the whole space.</p><p><img src="/webp/stretch-image.jpg-90-1788222796862.webp" srcset="`+K+`" alt="Stretch image" title="" width="760" height="748" loading="lazy" style="width:380px;"></p><p>If we enable the rounded field option, we will have this display</p><p><img src="/webp/rounded-field.jpg-90-1788222796849.webp" srcset="`+q+`" alt="Rounded field" title="" width="716" height="668" loading="lazy" style="width:358px;"></p><h2 id="field-cost" tabindex="-1">Field cost <a class="header-anchor" href="#field-cost" aria-label="Permalink to “Field cost”">​</a></h2><p>5️⃣ Next, we set the extra cost for each field and choose whether to include the items cost that are inside the field.</p><p><img src="/webp/field-cost.jpg-90-1788222796700.webp" srcset="`+J+`" alt="Field cost" title="" width="644" height="280" loading="lazy" style="width:322px;"></p><h2 id="using-templates" tabindex="-1">Using templates <a class="header-anchor" href="#using-templates" aria-label="Permalink to “Using templates”">​</a></h2><p>You can enable models which are field templates that your customer can pick from.</p><p>First, enable the models like this</p><p><img src="/webp/models-switch.jpg-90-1788222796806.webp" srcset="`+Y+`" alt="Models switch" title="" width="966" height="914" loading="lazy" style="width:483px;"></p><p>Then add any number of models by the clicking the add button</p><p><img src="/webp/add-model.jpg-90-1788222796635.webp" srcset="`+X+`" alt="Add model" title="" width="736" height="386" loading="lazy" style="width:368px;"></p><p>Then you can add fields to each model. The fields layout will be displayed directly.</p><p><img src="/webp/fields-preview.jpg-90-1788222796702.webp" srcset="`+Z+`" alt="Fields preview" title="" width="1682" height="1066" loading="lazy" style="width:841px;"></p><p>The models will be displayed in a separate tab in the customer interface</p><p><img src="/webp/models-tab.png-90-1788222796808.webp" srcset="`+Q+`" alt="Models tab" title="" width="1734" height="1276" loading="lazy" style="width:867px;"></p>`,48)]])}var te=e(I,[[`render`,$]]);export{F as __pageData,te as default};